ALTER TABLE site_config ADD COLUMN version bigint NOT NULL DEFAULT 1;
CREATE TABLE banner_slot (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,code varchar(60) NOT NULL UNIQUE,name varchar(100) NOT NULL);
COMMENT ON TABLE banner_slot IS '官网 Banner 位置';
COMMENT ON COLUMN banner_slot.code IS '位置编码';
CREATE TABLE banner (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,slot_code varchar(60) NOT NULL,title varchar(200) NOT NULL,subtitle text NOT NULL DEFAULT '',image_media_id bigint NOT NULL,mobile_image_media_id bigint,cta_text varchar(100) NOT NULL DEFAULT '',link text NOT NULL DEFAULT '',sort integer NOT NULL DEFAULT 0,enabled boolean NOT NULL DEFAULT false,starts_at timestamptz,ends_at timestamptz,version bigint NOT NULL DEFAULT 1,created_by bigint NOT NULL,updated_by bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
CREATE INDEX banner_slot_active ON banner(slot_code,sort,id) WHERE deleted_at IS NULL;
COMMENT ON TABLE banner IS '官网 Banner 投放';
COMMENT ON COLUMN banner.image_media_id IS '桌面图片素材标识';
COMMENT ON COLUMN banner.mobile_image_media_id IS '手机图片素材标识';
COMMENT ON COLUMN banner.starts_at IS '投放开始时间';
COMMENT ON COLUMN banner.ends_at IS '投放结束时间';
COMMENT ON COLUMN banner.version IS '并发版本';
